import java.util.Scanner;

public class Main {
    static final int MAXN = 1000005;
    static boolean[] visitedNodes = new boolean[MAXN];
    static final long MOD = 1000000007;

    static long powMod(long base, int exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % MOD;
            }
            base = (base * base) % MOD;
            exponent >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(powMod(p, (int)(p - 1)));
            sc.close();
            return;
        }
        if (k == 1) {
            System.out.println(powMod(p, (int)p));
            sc.close();
            return;
        }

        int groupCount = 0;
        for (int i = 1; i < p; i++) {
            if (visitedNodes[i]) continue;
            long j = i;
            while (!visitedNodes[(int)j]) {
                visitedNodes[(int)j] = true;
                j = (j * k) % p;
            }
            groupCount++;
        }
        System.out.println(powMod(p, groupCount));
        sc.close();
    }
}
